"""Final generated bytes retain their original, unspent vision allowance."""
import tempfile,unittest,hashlib
from pathlib import Path
from unittest.mock import Mock
from automation.agri_v2 import image_workflow as w,image_quality as q,family_lifecycle as f
from automation.agri_v2.parallel_pool import PoolDeferred
from automation.agri_v2.queue import atomic_json,load_json
import test_image_fallback as fixtures

class FinalImageReviewResumeTests(unittest.TestCase):
 def pending(self,folder,k,status='review_deferred'):
  p=folder/f'image-{k}.webp';p.write_bytes(('final-candidate-'+str(k)).encode())
  atomic_json(p.with_suffix('.quality.json'),{'status':status,'image_sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
  for stage,n,s in (('image-',4,'validated'),('vision-',3,'deferred')):
   atomic_json(f.row_path(folder,stage+str(k)),{'attempts':n,'status':s,'history':[{'attempts':i+1} for i in range(n)],'last_run_id':'old'})
  return p
 def test_final_generated_candidate_is_not_exhausted_before_last_review(self):
  for status in ('review_started','review_deferred','review_unavailable'):
   with tempfile.TemporaryDirectory() as td:
    folder=Path(td);self.pending(folder,1,status);self.assertFalse(w.exhausted(folder,1))
 def test_two_pending_final_images_resume_reviews_without_generation_or_budget_reset(self):
  with tempfile.TemporaryDirectory() as td:
   data,folder,t,a=fixtures.ImageFallbackTests().fixture(td);images=[self.pending(folder,k) for k in (1,2)];before=[p.read_bytes() for p in images]
   c=fixtures.FakeClient({1:[True],2:[True]});c.image=Mock(side_effect=AssertionError('No fifth generation'))
   r=w.advance(c,folder,t,a,'resume',data);self.assertEqual(r['status'],'images_ready');self.assertEqual(r['roles'],[1,2]);c.image.assert_not_called()
   for k,p,b in zip((1,2),images,before):
    self.assertEqual(p.read_bytes(),b);self.assertEqual(f.state(folder,'image-'+str(k))['attempts'],4);self.assertEqual(f.state(folder,'vision-'+str(k))['attempts'],4)
   q.require_all(folder,t,a)
 def test_repeated_last_review_deferrals_preserve_bytes_then_review_once(self):
  with tempfile.TemporaryDirectory() as td:
   data,folder,t,a=fixtures.ImageFallbackTests().fixture(td);p=self.pending(folder,1);before=p.read_bytes();c=fixtures.FakeClient({1:[True],2:[True]});original=c.review_image;calls=[]
   def review(blob,*args):
    calls.append(blob)
    if len(calls)<=2:raise PoolDeferred('Bounded model budget consumed')
    return original(blob,*args)
   c.review_image=review
   for run in ('wait-1','wait-2'):
    self.assertEqual(w.advance(c,folder,t,a,run,data)['status'],'images_deferred');self.assertEqual(f.state(folder,'vision-1')['attempts'],3);self.assertFalse(w.exhausted(folder,1));self.assertEqual(p.read_bytes(),before);self.assertFalse(w.selection_path(folder).exists())
   r=w.advance(c,folder,t,a,'resume',data);self.assertEqual(r['status'],'images_ready');self.assertEqual(len(c.images),1);self.assertEqual(f.state(folder,'vision-1')['attempts'],4);self.assertEqual(p.read_bytes(),before)
 def test_no_premature_single_image_fallback_while_final_review_pending(self):
  with tempfile.TemporaryDirectory() as td:
   data,folder,t,a=fixtures.ImageFallbackTests().fixture(td);w.advance(fixtures.FakeClient({1:[True],2:[True]}),folder,t,a,'old',data);w.selection_path(folder).unlink();self.pending(folder,2)
   with self.assertRaises(ValueError):w.seal_selection(folder,t,a,(1,))
 def test_fully_reviewed_rejection_and_vision_budget_still_exhaust(self):
  with tempfile.TemporaryDirectory() as td:
   folder=Path(td);p=self.pending(folder,1);atomic_json(p.with_suffix('.quality.json'),{'image_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'status':'reviewed','verdict':{'passed':False}});self.assertTrue(w.exhausted(folder,1))
   row=f.state(folder,'vision-1');row['attempts']=4;atomic_json(f.row_path(folder,'vision-1'),row);p.with_suffix('.quality.json').unlink();self.assertTrue(w.exhausted(folder,1))
